changeSet.sql:
SET QUOTED_IDENTIFIER ON; IF COL_LENGTH(N'app.MemberProgressAssessments', N'Height') IS NULL ALTER TABLE app.MemberProgressAssessments ADD Height DECIMAL(8, 2) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'RightArm') IS NULL ALTER TABLE app.MemberProgressAssessments ADD RightArm DECIMAL(8, 2) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'RightThigh') IS NULL ALTER TABLE app.MemberProgressAssessments ADD RightThigh DECIMAL(8, 2) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'VisceralFat') IS NULL ALTER TABLE app.MemberProgressAssessments ADD VisceralFat DECIMAL(5, 2) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'StrengthScore') IS NULL ALTER TABLE app.MemberProgressAssessments ADD StrengthScore DECIMAL(4, 1) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'EnduranceScore') IS NULL ALTER TABLE app.MemberProgressAssessments ADD EnduranceScore DECIMAL(4, 1) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'FlexibilityScore') IS NULL ALTER TABLE app.MemberProgressAssessments ADD FlexibilityScore DECIMAL(4, 1) NULL; IF COL_LENGTH(N'app.MemberProgressAssessments', N'CoreScore') IS NULL ALTER TABLE app.MemberProgressAssessments ADD CoreScore DECIMAL(4, 1) NULL; IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_Height' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_Height CHECK (Height IS NULL OR (Height > 0 AND Height <= 500)); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_RightArm' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_RightArm CHECK (RightArm IS NULL OR (RightArm > 0 AND RightArm <= 500)); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_RightThigh' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_RightThigh CHECK (RightThigh IS NULL OR (RightThigh > 0 AND RightThigh <= 500)); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_Visceral' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_Visceral CHECK (VisceralFat IS NULL OR (VisceralFat > 0 AND VisceralFat <= 60)); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_Strength' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_Strength CHECK (StrengthScore IS NULL OR StrengthScore BETWEEN 1 AND 10); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_Endurance' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_Endurance CHECK (EnduranceScore IS NULL OR EnduranceScore BETWEEN 1 AND 10); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_Flexibility' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_Flexibility CHECK (FlexibilityScore IS NULL OR FlexibilityScore BETWEEN 1 AND 10); ';
IF NOT EXISTS ( SELECT 1 FROM sys.check_constraints WHERE name = N'CK_MemberProgressAssessments_Core' AND parent_object_id = OBJECT_ID(N'app.MemberProgressAssessments') ) EXEC sys.sp_executesql N' ALTER TABLE app.MemberProgressAssessments ADD CONSTRAINT CK_MemberProgressAssessments_Core CHECK (CoreScore IS NULL OR CoreScore BETWEEN 1 AND 10); '; IF OBJECT_ID(N'app.MemberProgressPhotos', N'U') IS NULL BEGIN CREATE TABLE app.MemberProgressPhotos ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, AssessmentId UNIQUEIDENTIFIER NOT NULL, StorageKey NVARCHAR(200) NOT NULL, ContentType NVARCHAR(80) NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_MemberProgressPhotos PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_MemberProgressPhotos_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT FK_MemberProgressPhotos_MemberProgressAssessments FOREIGN KEY (AssessmentId) REFERENCES app.MemberProgressAssessments (Id), CONSTRAINT CK_MemberProgressPhotos_Type CHECK (ContentType IN (N'image/jpeg', N'image/png', N'image/webp')) ); CREATE INDEX IX_MemberProgressPhotos_Assessment ON app.MemberProgressPhotos (TenantId, AssessmentId) WHERE DeletedAt IS NULL; END
